<?php
require_once 'config/database.php';
require_once 'config/session.php';
require_once 'includes/tienda_lib.php';
require_login();
function esc($v){ return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
$errores=[]; $editar=null;
if ($_SERVER['REQUEST_METHOD']==='POST') { $accion=$_POST['accion']??''; $id=(int)($_POST['id']??0);
 if($accion==='guardar') { $nombre=trim($_POST['nombre']??''); $descripcion=trim($_POST['descripcion']??''); if($nombre==='')$errores[]='Escribe el nombre de la categoría.';
   if(!$errores){ try { if($id>0){$q=$pdo->prepare('UPDATE categorias SET nombre=?, descripcion=? WHERE id=?');$q->execute([$nombre,$descripcion?:null,$id]);t_flash_set('crm_ok','Categoría actualizada correctamente.');}else{$q=$pdo->prepare('INSERT INTO categorias(nombre,descripcion) VALUES(?,?)');$q->execute([$nombre,$descripcion?:null]);t_flash_set('crm_ok','Categoría creada correctamente.');} header('Location: categorias.php');exit;}catch(PDOException $e){$errores[]='No se pudo guardar. Comprueba que el nombre no esté repetido.';} }
   $editar=['id'=>$id,'nombre'=>$nombre,'descripcion'=>$descripcion];
 } elseif($accion==='eliminar' && $id>0){$q=$pdo->prepare('SELECT COUNT(*) FROM productos WHERE categoria_id=?');$q->execute([$id]); if((int)$q->fetchColumn()>0){t_flash_set('crm_ok','No se eliminó: hay productos asociados a esta categoría.');}else{$q=$pdo->prepare('DELETE FROM categorias WHERE id=?');$q->execute([$id]);t_flash_set('crm_ok','Categoría eliminada.');}header('Location: categorias.php');exit;}
}
if(!$editar && isset($_GET['editar'])){$q=$pdo->prepare('SELECT * FROM categorias WHERE id=?');$q->execute([(int)$_GET['editar']]);$editar=$q->fetch()?:null;}
$categorias=$pdo->query('SELECT c.*, (SELECT COUNT(*) FROM productos p WHERE p.categoria_id=c.id) AS productos_count FROM categorias c ORDER BY c.id DESC')->fetchAll();
$titulo='Categorías';$eyebrow='ORGANIZACIÓN DE INVENTARIO';$subtitulo='Organiza los productos por tipo y administra las categorías.';$activo='categorias';include 'includes/crm_top.php';
?>
<style>.manage-grid{display:grid;grid-template-columns:minmax(260px,340px) 1fr;gap:20px}.manage-form label{display:block;margin:12px 0 5px;font-weight:600}.manage-form input,.manage-form textarea{width:100%;padding:10px;border:1px solid #d1d5db;border-radius:8px;box-sizing:border-box;font:inherit}.manage-form button{margin-top:15px;background:#252b45;color:#fff;border:0;border-radius:8px;padding:10px 14px;cursor:pointer}.manage-table{width:100%;border-collapse:collapse}.manage-table th,.manage-table td{padding:12px 10px;text-align:left;border-bottom:1px solid #e5e7eb}.manage-table th{font-size:12px;color:#6b7280}.table-scroll{overflow-x:auto}.link-action{color:#3949ab;font-weight:600;text-decoration:none;margin-right:8px}.danger-action{color:#b91c1c;background:none;border:0;cursor:pointer;font:inherit}.form-panel,.table-panel{background:#fff;border-radius:14px;padding:20px;box-shadow:0 3px 14px #18213b0a}.subtle{color:#6b7280;font-size:13px}@media(max-width:850px){.manage-grid{grid-template-columns:1fr}}</style>
<?php if($errores): ?><div class="alert error"><?php foreach($errores as $err): ?><div><?=esc($err)?></div><?php endforeach; ?></div><?php endif; ?>
<div class="manage-grid"><section class="form-panel"><h2><?= $editar && (int)$editar['id']>0?'Editar categoría':'Nueva categoría' ?></h2><form class="manage-form" method="post"><input type="hidden" name="accion" value="guardar"><input type="hidden" name="id" value="<?=(int)($editar['id']??0)?>"><label>Nombre</label><input name="nombre" maxlength="100" required value="<?=esc($editar['nombre']??'')?>"><label>Descripción</label><textarea name="descripcion" rows="4" placeholder="Descripción opcional"><?=esc($editar['descripcion']??'')?></textarea><button type="submit"><?= $editar && (int)$editar['id']>0?'Guardar cambios':'Crear categoría' ?></button><?php if($editar && (int)$editar['id']>0): ?> <a class="link-action" href="categorias.php">Cancelar</a><?php endif; ?></form></section>
<section class="table-panel"><h2>Categorías registradas</h2><p class="subtle"><?=count($categorias)?> categoría(s)</p><div class="table-scroll"><table class="manage-table"><thead><tr><th>NOMBRE</th><th>DESCRIPCIÓN</th><th>PRODUCTOS</th><th>ACCIONES</th></tr></thead><tbody><?php if(!$categorias): ?><tr><td colspan="4">No hay categorías registradas.</td></tr><?php endif; foreach($categorias as $c): ?><tr><td><strong><?=esc($c['nombre'])?></strong></td><td><?=esc($c['descripcion']?:'—')?></td><td><?=(int)$c['productos_count']?></td><td><a class="link-action" href="categorias.php?editar=<?=(int)$c['id']?>">Editar</a><form method="post" style="display:inline" onsubmit="return confirm('¿Eliminar esta categoría?')"><input type="hidden" name="accion" value="eliminar"><input type="hidden" name="id" value="<?=(int)$c['id']?>"><button class="danger-action" type="submit">Eliminar</button></form></td></tr><?php endforeach; ?></tbody></table></div></section></div>
